const row = $input.first().json;
const rawEmotions = Array.isArray(row.raw_emotions) && row.raw_emotions.length > 0
  ? row.raw_emotions
  : Array.isArray(row.emotion_labels) && row.emotion_labels.length > 0
    ? row.emotion_labels
    : ['없음'];

const prompt = `다음 소설 문장에 대해 감정 라벨을 다시 검토해주세요.\n\n책: ${row.title} (${row.author})\n문장: ${row.quote}\n1차 감정 결과: ${rawEmotions.join(', ')}\n\n요구사항:\n- 문맥에 실제로 맞는 감정만 남길 것\n- 필요하면 라벨 수를 줄일 것\n- 설명 없이 JSON 배열만 반환할 것\n예: ["슬픔", "외로움"]`;

return [{
  json: {
    ...row,
    raw_emotions: rawEmotions,
    prompt
  }
}];

const response = $input.first().json;
const row = $('재검토 프롬프트 생성').item.json;

const verifyText = response?.choices?.[0]?.message?.content;
if (!verifyText) {
  throw new Error('Groq 2차 검증 응답 오류: ' + JSON.stringify(response).slice(0, 500));
}

const extractJSONArray = (source) => {
  const cleaned = source.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
  const start = cleaned.indexOf('[');
  const end = cleaned.lastIndexOf(']');
  if (start === -1 || end === -1 || end <= start) {
    return null;
  }
  return cleaned.slice(start, end + 1);
};

const tryParse = (raw) => {
  try {
    return JSON.parse(raw);
  } catch (e) {
    const repaired = raw
      .replace(/,\s*([}\]])/g, '$1')
      .replace(/[\u201C\u201D]/g, '"')
      .replace(/[\u2018\u2019]/g, "'");
    return JSON.parse(repaired);
  }
};

const rawJson = extractJSONArray(verifyText);
let emotion_labels = row.raw_emotions;
if (rawJson) {
  const parsed = tryParse(rawJson);
  if (Array.isArray(parsed) && parsed.length > 0) {
    emotion_labels = parsed;
  }
}

return [{
  json: {
    ...row,
    emotion_labels
  }
}];
